{"explanation":"Both big squares have side a+b, so they have equal area. On the left, four right triangles surround a tilted square of side c. Slide the same four triangles into the right square, and the leftover space becomes an a×a square and a b×b square. Removing the same four triangles from each side leaves c² = a² + b². Click the triangles to recolor them.","manimCode":"const a = 1.5, b = 2, s = a + b;
const L = [-5.5, -1.6], R = [1.5, -1.6];
const P = (o, x, y) => [o[0] + x, o[1] + y, 0];

function sq(o, color) {
  const p = new Polygon({ vertices: [P(o,0,0), P(o,s,0), P(o,s,s), P(o,0,s)], color: color });
  p.setFill(BLACK, 0);
  return p;
}
function tri(o, pts) {
  const p = new Polygon({ vertices: pts.map(q => P(o, q[0], q[1])), color: WHITE });
  p.setFill(BLUE, 0.7);
  return p;
}

const outL = sq(L, WHITE), outR = sq(R, WHITE);
await scene.play(new Create(outL), new Create(outR));

// Left: four triangles around a tilted square
const leftTris = [
  tri(L, [[0,0],[b,0],[0,a]]),
  tri(L, [[b,0],[s,0],[s,b]]),
  tri(L, [[s,b],[s,s],[a,s]]),
  tri(L, [[a,s],[0,s],[0,a]])
];
const cSq = new Polygon({ vertices: [P(L,b,0), P(L,s,b), P(L,a,s), P(L,0,a)], color: YELLOW });
cSq.setFill(YELLOW, 0.35);
const cLabel = new Text({ text: 'c²', color: YELLOW, fontSize: 36 });
cLabel.moveTo(P(L, s/2, s/2));

const title = new Text({ text: 'Same four triangles, same big square (side a+b)', color: WHITE, fontSize: 26 });
title.moveTo([0, 3.3, 0]);
scene.add(title);

for (const t of leftTris) scene.add(t);
await scene.play(new FadeIn(cSq), new FadeIn(cLabel));
await scene.wait(1);

// Right: rearranged triangles
const rightTargets = [
  tri(R, [[0,b],[b,b],[b,s]]),
  tri(R, [[0,b],[0,s],[b,s]]),
  tri(R, [[b,0],[s,0],[s,b]]),
  tri(R, [[b,0],[b,b],[s,b]])
];
const copies = leftTris.map(t => {
  const c = tri(L, [[0,0],[1,0],[0,1]]);
  c.setVertices(t.getVertices());
  c.setFill(BLUE, 0.7);
  return c;
});
for (const c of copies) scene.add(c);
await scene.play(...copies.map((c, i) => new Transform(c, rightTargets[i])));
await scene.wait(0.5);

const aSq = new Polygon({ vertices: [P(R,b,b), P(R,s,b), P(R,s,s), P(R,b,s)], color: GREEN });
aSq.setFill(GREEN, 0.4);
const bSq = new Polygon({ vertices: [P(R,0,0), P(R,b,0), P(R,b,b), P(R,0,b)], color: RED });
bSq.setFill(RED, 0.4);
const aLab = new Text({ text: 'a²', color: GREEN, fontSize: 30 });
aLab.moveTo(P(R, b + a/2, b + a/2));
const bLab = new Text({ text: 'b²', color: RED, fontSize: 34 });
bLab.moveTo(P(R, b/2, b/2));
await scene.play(new FadeIn(aSq), new FadeIn(bSq), new FadeIn(aLab), new FadeIn(bLab));

const result = new MathTex({ latex: 'c^2 = a^2 + b^2' });
await result.waitForRender();
result.moveTo([0, -3.1, 0]);
await scene.play(new Write(result));

// Interactivity: click triangles to recolor
const palette = [BLUE, TEAL, PURPLE, ORANGE];
let k = 0;
for (const t of leftTris.concat(copies)) {
  makeHoverable(t, scene, { hoverScale: 1.05 });
  makeClickable(t, scene, { onClick: (m) => { k = (k + 1) % palette.length; m.setFill(palette[k], 0.7); } });
}

await scene.wait(999999);"}

